const express = require('express');
const http = require('http');
const { Server } = require('socket.io');
const { randomInt } = require('crypto');

const app = express();
const server = http.createServer(app);
const io = new Server(server, {
    cors: { origin: '*', methods: ['GET', 'POST'] }
});

// Shared, server-authoritative ROUND DISPLAY only.
// Betting, wallet debits and payouts are intentionally NOT enabled here.
// Results are generated by this server, not by individual phones.
const GAME_ROOM = 'maxchat_greedy_lion_global';
const ROUND_MS = 20_000;
const FOOD_COUNT = 8;
let roundNumber = 1;
let roundStartsAt = Date.now();
let roundEndsAt = roundStartsAt + ROUND_MS;
let history = []; // Last eight completed server rounds, in chronological order.

function gameState() {
    return {
        roundNumber,
        roundStartsAt,
        roundEndsAt,
        serverTime: Date.now(),
        phase: 'betting_disabled',
        history: history.slice(),
        bettingEnabled: false
    };
}

function closeDueRound() {
    const now = Date.now();
    if (now < roundEndsAt) return;

    // If the process was paused or asleep, do not invent skipped outcomes.
    const finishedRound = roundNumber;
    const winningIndex = randomInt(FOOD_COUNT);
    const result = {
        roundNumber: finishedRound,
        winningIndex,
        completedAt: now,
        hasSettledBets: false
    };
    history.push(result);
    if (history.length > 8) history.shift();
    io.to(GAME_ROOM).emit('greedy_lion_round_result', result);

    roundNumber += 1;
    roundStartsAt = now;
    roundEndsAt = now + ROUND_MS;
    io.to(GAME_ROOM).emit('greedy_lion_state', gameState());
}

// Keep all clients in sync without starting a timer on each phone.
setInterval(() => {
    closeDueRound();
    io.to(GAME_ROOM).emit('greedy_lion_clock', {
        roundNumber,
        roundEndsAt,
        serverTime: Date.now()
    });
}, 1000);

io.on('connection', (socket) => {
    console.log('مستخدم متصل بالسيرفر');

    // Existing voice events: unchanged.
    socket.on('join_room', (data) => {
        const { roomId, userId, userName } = data;
        socket.join(roomId);
        socket.to(roomId).emit('user_joined_room', { userId, userName });
    });

    socket.on('toggle_mute', (data) => {
        const { roomId, userId, isMuted } = data;
        io.to(roomId).emit('user_toggle_mute', { userId, isMuted });
    });

    socket.on('sit_on_seat', (data) => {
        const { roomId, userId, seatIndex } = data;
        io.to(roomId).emit('user_sat_on_seat', { userId, seatIndex });
    });

    socket.on('leave_seat', (data) => {
        const { roomId, userId } = data;
        io.to(roomId).emit('user_left_seat', { userId });
    });

    socket.on('start_audio_stream', (data) => {
        const { roomId, userId } = data;
        socket.to(roomId).emit('user_started_audio', { userId });
    });

    socket.on('stop_audio_stream', (data) => {
        const { roomId, userId } = data;
        socket.to(roomId).emit('user_stopped_audio', { userId });
    });

    socket.on('voice_data', (data) => {
        const { roomId, audioBuffer, userId } = data;
        socket.to(roomId).emit('voice_data', { audioBuffer, userId });
    });

    // New game events, isolated from voice rooms.
    socket.on('greedy_lion_join', () => {
        closeDueRound();
        socket.join(GAME_ROOM);
        socket.emit('greedy_lion_state', gameState());
    });

    socket.on('greedy_lion_leave', () => {
        socket.leave(GAME_ROOM);
    });

    socket.on('disconnect', () => {
        console.log('مستخدم غادر السيرفر');
    });
});

const PORT = process.env.PORT || 10000;
server.listen(PORT, () => {
    console.log(`السيرفر الصوتي يعمل بنجاح على المنفذ ${PORT}`);
});
